steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      issues(first: 20, filter: {
        title: {contains: \"login redirect\"}
      }) {
        nodes {
          id
          identifier
          title
          createdAt
          team { name }
          user { name email }
          assignee { name }
        }
      }
    }"
  }'
